package org.apache.commons.cli.help;

import org.junit.Test;
import static org.junit.Assert.*;

public class PadTests {

    @Test
    public void testCenterPaddingEven() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.CENTER)
                .indent(0)
                .maxWidth(10)
                .get();

        CharSequence res = style.pad(false, "hi");
        assertEquals("    hi    ", res.toString());
    }

    @Test
    public void testCenterPaddingUnsetWithIndent() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.CENTER)
                .indent(3)
                .maxWidth(TextStyle.UNSET_MAX_WIDTH)
                .get();

        CharSequence res = style.pad(true, "hi");
        // indent=3 -> padLen=3 -> left=(3+1)/2=2, right=1
        assertEquals("  hi ", res.toString());
    }

    @Test
    public void testLeftPaddingWithExactIndentAvailable_shouldIndentBeforeText() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.LEFT)
                .indent(2)
                .maxWidth(5) // text "abc" length=3 -> restLen = 2 == indent
                .get();

        CharSequence res = style.pad(true, "abc");
        // Expected behaviour: when indent fits exactly, the indent should be applied before the text
        // so we expect two leading spaces followed by "abc".
        assertEquals("  abc", res.toString());
    }

    @Test
    public void testTextLengthGreaterOrEqualReturnsSameInstance() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.LEFT)
                .indent(1)
                .maxWidth(3)
                .get();

        StringBuilder text = new StringBuilder("abc"); // length == maxWidth
        CharSequence out = style.pad(false, text);
        // When text length >= maxWidth, original CharSequence should be returned unchanged (same instance)
        assertSame(text, out);
    }

    @Test
    public void testRightPaddingWithIndentAndMaxWidth() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.RIGHT)
                .indent(3)
                .maxWidth(10)
                .get();

        CharSequence res = style.pad(true, "hey");
        // maxWidth 10, text length 3 -> restLen = 7, restLen > indent (3)
        // indentPad = 3, restLen -= indent -> 4; final leading spaces = 3 + 4 = 7
        assertEquals("       hey", res.toString()); // 7 spaces then "hey"
    }

    @Test
    public void testCenterPaddingOddDistribution() {
        TextStyle style = TextStyle.builder()
                .alignment(TextStyle.Alignment.CENTER)
                .indent(0)
                .maxWidth(8)
                .get();

        CharSequence res = style.pad(false, "x");
        // maxWidth 8, text length 1 -> padLen = 7, left = (7+1)/2 = 4, right = 3
        assertEquals("    x   ", res.toString());
    }
}

